const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let user=readDemo('petopia_user',null);if(user && (typeof user !== 'object' || !user.name))user=null;
let favorites=new Set(readDemo('petopia_favs',[]));
let cart=readDemo('petopia_cart',{});
let orders=readDemo('petopia_orders',[]);
let applications=readDemo('petopia_apps',[]);
let bookings=readDemo('petopia_bookings',[]);
let donations=readDemo('petopia_donations',[]);
let posts=readDemo('petopia_posts',[])||[{id:1,name:'Demo User',time:'2 hours ago',text:'Just adopted Luna from the Bangkok shelter! She is the sweetest. 🐾',likes:4,liked:false,comments:['Congratulations!'] }];
let species='all',ageFilter='all',shopCat='all',communityTopic='All',compat=demoStorage.getItem('petopia_compat')==='1',currentPet=1,authMode='signin',lang=demoStorage.getItem('petopia_lang')||'en';
let quizIndex=0,quizAnswers=readDemo('petopia_quiz',{});if(!PetopiaCore.validAnswers(quizAnswers)){quizAnswers={};compat=false;}
function fmt(n){return '฿'+Number(n||0).toLocaleString('en-US')}
function save(key,val){demoStorage.setItem(key,JSON.stringify(val))}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200)}



function requireLogin(next){if(!user){demoStorage.setItem('petopia_after_login',next||'browse');showPage('auth');toast('Start a demo session to continue');return false}return true}
function updateUserUI(){const signed=!!user;$('#loginBtn').classList.toggle('hidden',signed);$('#profileBtn').classList.toggle('hidden',!signed);$('#logoutBtn').classList.toggle('hidden',!signed);$('#favBtn').dataset.count=favorites.size;updateCartUI();applyLang()}
function translateCoreText(core){
  if(!core)return core;
  if(TH_TEXT[core])return TH_TEXT[core];
  let m;
  if((m=core.match(/^(\d+) items?$/)))return m[1]+' รายการ';
  if((m=core.match(/^(\d+) pets?$/)))return m[1]+' ตัว';
  if((m=core.match(/^(\d+)% Match$/)))return 'เข้ากัน '+m[1]+'%';
  if((m=core.match(/^(\d+) years? old$/)))return 'อายุ '+m[1]+' ปี';
  if((m=core.match(/^Question (\d+) of (\d+)$/)))return 'คำถามที่ '+m[1]+' จาก '+m[2];
  if((m=core.match(/^Adopt (.+)$/)))return 'ขอรับเลี้ยง '+m[1];
  if((m=core.match(/^Why would you like to adopt (.+)\?$/)))return 'ทำไมคุณจึงต้องการรับเลี้ยง '+m[1]+'?';
  if((m=core.match(/^Adoption Chat for (.+)$/)))return 'แชตรับเลี้ยงสำหรับ '+m[1];
  if((m=core.match(/^Hi! Thank you for your interest in (.+)\. How can we help\?$/)))return 'สวัสดีค่ะ/ครับ ขอบคุณที่สนใจ '+m[1]+' มีอะไรให้เราช่วยไหม?';
  if((m=core.match(/^Insurance Quote · (.+)$/)))return 'ใบเสนอราคาประกัน · '+translateCoreText(m[1]);
  if((m=core.match(/^Booking · (.+)$/)))return 'การจอง · '+translateCoreText(m[1]);
  if((m=core.match(/^Grooming · (.+)$/)))return 'กรูมมิ่ง · '+translateCoreText(m[1]);
  if((m=core.match(/^Confirm (.+) Premium$/)))return 'ยืนยัน Premium '+m[1];
  if((m=core.match(/^Estimated (฿[\d,]+)\/month$/)))return 'ประมาณ '+m[1]+'/เดือน';
  if((m=core.match(/^Estimated premium: (฿[\d,]+)\/month$/)))return 'เบี้ยประกันโดยประมาณ: '+m[1]+'/เดือน';
  if((m=core.match(/^(฿[\d,]+) each$/)))return m[1]+' ต่อชิ้น';
  if((m=core.match(/^Thank you — demo receipt (฿[\d,]+)$/)))return 'ขอบคุณ — ใบเสร็จทดลอง '+m[1];
  if((m=core.match(/^Reference: (.+)$/)))return 'เลขอ้างอิง: '+m[1];
  if((m=core.match(/^([\d,]+) Likes?$/)))return m[1]+' ถูกใจ';
  return core;
}
function translateValue(value){
  if(lang!=='th'||typeof value!=='string')return value;
  const lead=value.match(/^\s*/)[0],trail=value.match(/\s*$/)[0],core=value.trim();
  return lead+translateCoreText(core)+trail;
}
function translateNodeTree(root){
  if(!root)return;
  const start=root.nodeType===Node.TEXT_NODE?root:root;
  const nodes=[];
  if(start.nodeType===Node.TEXT_NODE)nodes.push(start);
  else{
    const walker=document.createTreeWalker(start,NodeFilter.SHOW_TEXT,{acceptNode(node){const p=node.parentElement;if(!p||['SCRIPT','STYLE','NOSCRIPT'].includes(p.tagName))return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT;}});
    let n;while(n=walker.nextNode())nodes.push(n);
  }
  nodes.forEach(node=>{
    if(node._petopiaEn===undefined)node._petopiaEn=node.nodeValue;
    node.nodeValue=lang==='th'?translateValue(node._petopiaEn):node._petopiaEn;
  });
  const elements=start.nodeType===Node.ELEMENT_NODE?[start,...start.querySelectorAll('*')]:[];
  elements.forEach(el=>{
    ['placeholder','title','aria-label'].forEach(attr=>{
      if(!el.hasAttribute||!el.hasAttribute(attr))return;
      el._petopiaAttrs=el._petopiaAttrs||{};
      if(el._petopiaAttrs[attr]===undefined)el._petopiaAttrs[attr]=el.getAttribute(attr);
      el.setAttribute(attr,lang==='th'?translateValue(el._petopiaAttrs[attr]):el._petopiaAttrs[attr]);
    });
  });
}
let languageRendering=false;
function applyLang(root=document.body){
  languageRendering=true;
  document.documentElement.lang=lang==='th'?'th':'en';
  document.body.classList.toggle('lang-th',lang==='th');
  translateNodeTree(root);
  const lb=$('#langBtn');
  if(lb){lb.textContent=lang==='en'?'🌐 ไทย':'🌐 EN';lb.title=lang==='en'?'เปลี่ยนเป็นภาษาไทย':'Switch to English';lb.setAttribute('aria-label',lb.title)}
  languageRendering=false;
}
const languageObserver=new MutationObserver(mutations=>{
  if(languageRendering||lang!=='th')return;
  languageRendering=true;
  mutations.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===Node.ELEMENT_NODE||n.nodeType===Node.TEXT_NODE)translateNodeTree(n)}));
  languageRendering=false;
});
languageObserver.observe(document.body,{childList:true,subtree:true});
